    Bug 2047116 - Wait for the scrolled event box to be rendered before measuring in the calendar dialog position tests. r=arschmitz

    showEvent() scrolled the target event box into view then returned it for the
    position/tolerance checks, waiting only on scrollend / a 50ms timeout / one rAF.
    waitForEventBoxAt only waits for the box to exist (not to be laid out), and the
    scroll can re-render/recycle the box, so intermittently (notably the Hour 0 /
    top-of-view case) the returned box had an empty {0, 0, 0, 0} getBoundingClientRect.
    checkTolerance then measured a phantom target at the origin and the "target
    tolerance" assertions failed -> Test timed out.

    Replace the timing-based wait with a readiness gate: after scrolling, re-fetch
    the current event box and wait until it is actually visible before returning it,
    so callers always measure a real rect.

    Differential Revision: https://phabricator.services.mozilla.com/D310472

diff --git a/mail/components/calendar/test/browser/head.js b/mail/components/calendar/test/browser/head.js
index 7a76a55ee5b..a87e5ec179c 100644
--- a/mail/components/calendar/test/browser/head.js
+++ b/mail/components/calendar/test/browser/head.js
@@ -289,21 +289,18 @@ async function showEvent({
     1
   );

-  const { promise, resolve } = Promise.withResolvers();
-  eventBox.ownerDocument.addEventListener("scrollend", resolve, true);
-
   eventBox.scrollIntoView({ behavior: "instant", block, inline });

-  const timeout = setTimeout(resolve, 50);
-
-  await promise;
-
-  clearTimeout(timeout);
-  eventBox.ownerDocument.removeEventListener("scrollend", resolve, true);
-
-  await new Promise(eventBox.documentGlobal.requestAnimationFrame);
-
-  return eventBox;
+  // scrollIntoView can re-render/recycle the event box, and waitForEventBoxAt
+  // only waits for the box to exist, not to be laid out. Re-fetch the current
+  // box and wait until it is actually rendered before returning it, so callers
+  // measure a real rect instead of an empty {0, 0, 0, 0} one.
+  let scrolledBox;
+  await TestUtils.waitForCondition(() => {
+    scrolledBox = weekView.getEventBoxAt(window, targetDate.getDay() + 1, 1);
+    return scrolledBox && BrowserTestUtils.isVisible(scrolledBox);
+  }, "scrolled event box should exist and be laid out");
+  return scrolledBox;
 }

